(function(){
 const definitions={
  owner:{eyebrow:'SHOP OWNER WORKSPACE',title:'Run the whole business from one protected workspace.',description:'Manage shop setup, workers, subscriptions, payments, reports and the sales ledger. Owner-only billing remains separate from worker operations.',role:'shop_owner',target:'../?workspace=owner&tab=overview',modules:[['01','Business setup','Company profile, up to three shop images, map pin and payment methods.'],['02','Team and access','Create up to seven worker accounts and grant purchasing privileges explicitly.'],['03','Finance and control','Subscriptions, FIFO profit, expenses, ledger attribution and reports.']]},
  worker:{eyebrow:'WORKER POS',title:'Fast sales and dispatch without owner-only access.',description:'Workers receive only the tools their shop owner assigns. Every sale and purchasing action records the authenticated worker who completed it.',role:'worker',target:'../?workspace=worker&tab=sell',modules:[['01','Point of sale','Create multi-item carts and sell singular units or full cases.'],['02','Dispatch','Review confirmed customer orders and prepare them for collection or delivery.'],['03','Offline queue','Keep account-bound actions on the device until that same worker reconnects.']]},
  inventory:{eyebrow:'INVENTORY CONTROL',title:'One stock truth across retail and wholesale.',description:'Track base units, full cases, stock movements, purchase batches and live availability. Queued offline movements remain isolated by user and shop.',role:'shop_owner or worker',target:'../?workspace=owner&tab=sync',modules:[['01','Unit conversion','Cases deduct case size × quantity while individual sales deduct one base unit each.'],['02','Movement history','Sales, restocks, returns, damage and corrections receive idempotent action IDs.'],['03','Realtime availability','Supabase Realtime refreshes public stock when a confirmed movement reaches the database.']]},
  purchasing:{eyebrow:'PURCHASING & EXPENSES',title:'Accurate profit when supplier prices change.',description:'Record each purchase as its own cost layer. FIFO allocation consumes the oldest remaining stock cost first and preserves morning and afternoon price differences.',role:'shop_owner or authorised worker',target:'../?workspace=owner&tab=purchasing',modules:[['01','Purchase batches','Capture supplier, invoice, quantity, purchase price and receiving user.'],['02','FIFO costing','Calculate cost of goods sold from actual remaining purchase layers.'],['03','Expenses','Authorised purchasing workers can record procurement expenses with attribution.']]},
  account:{eyebrow:'CUSTOMER ACCOUNT',title:'Orders, payment reviews and deliveries in one place.',description:'Browsing remains public. A customer account is required only to order, submit payment proof, choose a courier and track delivery.',role:'customer',target:'../?customer=account',modules:[['01','Order history','See pending, approved, rejected and fulfilled orders.'],['02','Payment status','View the shop confirmation note without exposing another customer’s order.'],['03','Delivery tracking','Compare courier bids and follow the assigned courier after acceptance.']]},
  cart:{eyebrow:'CUSTOMER CHECKOUT',title:'A focused cart and payment-proof route.',description:'Build a shop-specific cart, confirm live availability, view the owner’s payment details and submit image or text proof for review.',role:'customer',target:'../?customer=cart',modules:[['01','Live stock check','Unavailable products are not offered for purchase.'],['02','Unit or case','Retail, wholesale and hybrid shop rules determine available package options.'],['03','Manual confirmation','Stock and ledger entries post only after an authorised shop user approves payment.']]}
 };
 const key=document.body.dataset.module;
 const item=definitions[key];
 if(!item)return;
 document.title=`ZWConnect ${key[0].toUpperCase()+key.slice(1)}`;
 document.querySelector('[data-eyebrow]').textContent=item.eyebrow;
 document.querySelector('[data-title]').textContent=item.title;
 document.querySelector('[data-description]').textContent=item.description;
 document.querySelector('[data-role]').textContent=item.role;
 document.querySelectorAll('[data-open-module]').forEach(link=>link.href=item.target);
 document.querySelector('[data-module-cards]').innerHTML=item.modules.map(([number,title,description])=>`<article class="module-card"><span>${number}</span><h3>${title}</h3><p>${description}</p></article>`).join('');
})();
